process FGBIO_ZIPPERBAMS {
    tag "${meta.id}"
    label 'process_single'

    conda "${moduleDir}/environment.yml"
    container "${workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container
        ? 'https://community-cr-prod.seqera.io/docker/registry/v2/blobs/sha256/4d/4d1150a2e123f49f8c268f0ab429847afae642376fa52af713b846b084df4a9f/data'
        : 'community.wave.seqera.io/library/fgbio:3.1.2--6e9400d507a9dc55'}"

    input:
    tuple val(meta), path(mapped_bam), path(unmapped_bam)
    tuple val(meta2), path(fasta), path(index), path(dict)

    output:
    tuple val(meta), path("${prefix}.bam"), emit: bam
    tuple val("${task.process}"), val('fgbio'), eval('fgbio --version 2>&1 | tr -d "[:cntrl:]" | sed -e "s/^.*Version: //;s/\\[.*$//"'), topic: versions, emit: versions_fgbio

    when:
    task.ext.when == null || task.ext.when

    script:
    def args = task.ext.args ?: ''
    // fgbio common options
    def args2 = task.ext.args2 ?: ''
    // fgbio tool options
    prefix = task.ext.prefix ?: "${meta.id}_zipped"
    def mem_gb = task.memory ? Math.max(1, task.memory.giga - 1) : 8
    if (!task.memory) {
        log.info('[fgbio ZipperBams] Available memory not known - defaulting to 8GB. Specify process memory requirements to change this.')
    }

    if ("${unmapped_bam}" == "${prefix}.bam") {
        error("Input and output names are the same, use \"task.ext.prefix\" to disambiguate!")
    }
    if ("${mapped_bam}" == "${prefix}.bam") {
        error("Input and output names are the same, use \"task.ext.prefix\" to disambiguate!")
    }
    if (!args.contains('--async-io=')) {
        args = "--async-io=true ${args}"
    }
    if (!args.contains('--compression ')) {
        args = "--compression 0 ${args}"
    }
    """
    fgbio -Xmx${mem_gb}g \\
        ${args} \\
        ZipperBams \\
        --unmapped ${unmapped_bam} \\
        --input ${mapped_bam} \\
        --ref ${fasta} \\
        ${args2} \\
        --output ${prefix}.bam
    """

    stub:
    prefix = task.ext.prefix ?: "${meta.id}_zipped"
    if ("${unmapped_bam}" == "${prefix}.bam") {
        error("Input and output names are the same, use \"task.ext.prefix\" to disambiguate!")
    }
    if ("${mapped_bam}" == "${prefix}.bam") {
        error("Input and output names are the same, use \"task.ext.prefix\" to disambiguate!")
    }

    """
    touch ${prefix}.bam
    """
}

nextflow_process {

    name "Test Process FGBIO_ZIPPERBAMS"
    script "../main.nf"
    process "FGBIO_ZIPPERBAMS"

    tag "modules"
    tag "modules_nfcore"
    tag "fgbio"
    tag "fgbio/zipperbams"

    test("sarscov2 - bam") {
        config "./nextflow.config"

        when {
            params {
                fgbio_args  = ''
                fgbio_args2 = '--tags-to-reverse Consensus --tags-to-revcomp Consensus'
            }
            process {
                """
                input[0] = [
                            [ id:'test', single_end:false ],
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/umi/test.paired_end.duplex_umi_mapped.bam', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/umi/test.paired_end.duplex_umi_unmapped.bam', checkIfExists: true)
                        ]
                input[1] = [
                            [ id:'genome'],
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.dict', checkIfExists: true)
                        ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("sarscov2 - bam - stub") {

        options "-stub"

        when {
            params {
                fgbio_args  = ''
                fgbio_args2 = '--tags-to-reverse Consensus --tags-to-revcomp Consensus'
            }
            process {
                """
                input[0] = [
                            [ id:'test', single_end:false ],
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/umi/test.paired_end.duplex_umi_mapped.bam', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/umi/test.paired_end.duplex_umi_unmapped.bam', checkIfExists: true)
                        ]
                input[1] = [
                            [ id:'genome'],
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta.fai', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.dict', checkIfExists: true)
                        ]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

